CREATE TABLE IF NOT EXISTS employees(id BIGSERIAL PRIMARY KEY,name VARCHAR(150) NOT NULL,registration VARCHAR(50) UNIQUE NOT NULL,profile VARCHAR(30) NOT NULL,unit VARCHAR(100),active BOOLEAN DEFAULT TRUE,updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS certifications(id BIGSERIAL PRIMARY KEY,employee_id BIGINT REFERENCES employees(id),type VARCHAR(120) NOT NULL,code VARCHAR(80),issuer VARCHAR(120),issued_at DATE,expires_at DATE,status VARCHAR(30) NOT NULL);
CREATE TABLE IF NOT EXISTS availabilities(id BIGSERIAL PRIMARY KEY,employee_id BIGINT REFERENCES employees(id),start_at TIMESTAMPTZ NOT NULL,end_at TIMESTAMPTZ NOT NULL,kind VARCHAR(30) NOT NULL);
CREATE TABLE IF NOT EXISTS shifts(id BIGSERIAL PRIMARY KEY,code VARCHAR(30) UNIQUE NOT NULL,name VARCHAR(120) NOT NULL,unit VARCHAR(100),start_time TIME NOT NULL,end_time TIME NOT NULL,required_count INT DEFAULT 1,required_certification VARCHAR(120),status VARCHAR(30) DEFAULT 'ATIVO');
CREATE TABLE IF NOT EXISTS schedules(id BIGSERIAL PRIMARY KEY,shift_id BIGINT REFERENCES shifts(id),schedule_date DATE,status VARCHAR(30));
CREATE TABLE IF NOT EXISTS allocations(id BIGSERIAL PRIMARY KEY,schedule_id BIGINT REFERENCES schedules(id),employee_id BIGINT REFERENCES employees(id),status VARCHAR(30),created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS domain_events(id BIGSERIAL PRIMARY KEY,event_type VARCHAR(80),status VARCHAR(30),payload JSONB,created_at TIMESTAMPTZ DEFAULT NOW());
